                ${faqItems.map((item, index) => FAQItem({ item, index })).join("")}
              </section>
            </main>
            <footer>
              <p>Use each question button to reveal or hide the answer.</p>
            </footer>
          </div>
        `;
      }

      function FAQItem({ item, index }) {
        const isOpen = state.openItems.has(index);
        const panelId = `faq-panel-${index}`;
        const buttonId = `faq-button-${index}`;

        return `
          <div class="example">
            <h2>
