             "Kneading is a comforting behavior that begins in kittenhood. Adult cats often knead soft surfaces when they feel safe, content, or ready to rest."
         },
         {
           question: "Should indoor cats still see a veterinarian?",
           answer:
             "Yes. Indoor cats still need regular wellness exams, vaccines recommended by a veterinarian, dental care, parasite prevention, and help catching health issues early."
         },
         {
           question: "How can I tell if my cat is happy?",
           answer:
             "Relaxed posture, slow blinking, upright tail greetings, gentle head bumps, normal eating habits, playfulness, and choosing to be near you are common signs of a comfortable cat."
         }
       ];

       const state = {
         openItems: new Set()
       };

       function escapeHtml(value) {
         return value
           .replaceAll("&", "&amp;")
           .replaceAll("<", "&lt;")
           .replaceAll(">", "&gt;")
           .replaceAll('"', "&quot;")
           .replaceAll("'", "&#039;");
       }

       function App() {
         return `
           <div class="page-shell">
             <main id="main-content" tabindex="-1">
               <header>
                 <p class="eyebrow">Cat care basics</p>
                 <h1>Frequently Asked Questions About Cats</h1>
                 <p class="intro">
                   Quick, practical answers for understanding your feline friend,
                   from everyday behavior to routine care.
                 </p>
               </header>
               <section class="faq-list" aria-label="Cat questions and answers">
                 ${faqItems.map((item, index) => FAQItem({ item, index })).join("")}
               </section>
             </main>
             <footer>
               <p>Use each question button to reveal or hide the answer.</p>
             </footer>
           </div>
         `;
       }

       function FAQItem({ item, index }) {
         const isOpen = state.openItems.has(index);
         const panelId = `faq-panel-${index}`;
         const buttonId = `faq-button-${index}`;

         return `
           <div class="example">
             <h2>
               <button
                 class="question-button"
                 id="${buttonId}"
                 type="button"
                 aria-expanded="${isOpen}"
                 aria-controls="${panelId}"
                 data-index="${index}"
               >
                 <span>${escapeHtml(item.question)}</span>
                 <span class="icon" aria-hidden="true">${isOpen ? "&minus;" : "+"}</span>
               </button>
             </h2>
             <div
               class="details"
               id="${panelId}"
               aria-labelledby="${buttonId}"
               ${isOpen ? "" : "hidden"}
             >
               <p>${escapeHtml(item.answer)}</p>
             </div>
           </div>
         `;
       }

       function render() {
         document.getElementById("root").innerHTML = App();
       }

       document.addEventListener("click", (event) => {
         const button = event.target.closest(".question-button");

         if (!button) {
           return;
         }

         const index = Number(button.dataset.index);

         if (state.openItems.has(index)) {
           state.openItems.delete(index);
         } else {
           state.openItems.add(index);
         }

         render();
         document.getElementById(`faq-button-${index}`).focus();
       });

       render();
     </script>
   </body>
